return ['domain'=>'publishpress-hub','plural-forms'=>'nplurals=1; plural=0;','language'=>'vi','project-id-version'=>'PublishPress Hub 1.2.0','pot-creation-date'=>'2026-11-16T12:00:34+00:00','po-revision-date'=>'2026-11-16 13:51+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Hub'=>'PublishPress Hub','Centralized management hub for all PublishPress plugins - install, update, and manage licenses from one dashboard.'=>'Trung tâm quản lý tập trung cho tất cả các plugin PublishPress - cài đặt, cập nhật và quản lý giấy phép từ một bảng điều khiển.','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Please wait while we load the components showcase...'=>'Vui lòng chờ trong khi chúng tôi tải trình diễn các thành phần...','AI Connections'=>'Kết nối AI','Please wait while we load AI connections...'=>'Vui lòng chờ trong khi chúng tôi tải các kết nối AI...','Please wait while we load the plugins dashboard...'=>'Vui lòng chờ trong khi chúng tôi tải bảng điều khiển các plugin...','Settings'=>'Cài đặt','Please wait while we load the settings page...'=>'Vui lòng chờ trong khi chúng tôi tải trang cài đặt...','You do not have sufficient permissions to access this page.'=>'Bạn không có đủ quyền để truy cập trang này.','Welcome'=>'Chào mừng','Please wait while we load the welcome page...'=>'Vui lòng chờ trong khi chúng tôi tải trang chào mừng...','Language pack has not been checked yet.'=>'Gói ngôn ngữ chưa được kiểm tra.','Site locale is English. No language pack is downloaded.'=>'Ngôn ngữ của trang là tiếng Anh. Không có gói ngôn ngữ nào được tải xuống.','No language packs are registered.'=>'Không có gói ngôn ngữ nào được đăng ký.','Language pack directory is not available.'=>'Thư mục gói ngôn ngữ không có sẵn.','Language pack for %1$s (%2$s) matches %3$s.'=>'Gói ngôn ngữ cho %1$s (%2$s) khớp với %3$s.','Language pack for %1$s (%2$s) installed for %3$s.'=>'Gói ngôn ngữ cho %1$s (%2$s) đã được cài đặt cho %3$s.','Language pack URL was rejected.'=>'URL gói ngôn ngữ đã bị từ chối.','Language pack download failed for %1$s (%2$s). The installed pack was left in place.'=>'Tải gói ngôn ngữ không thành công cho %1$s (%2$s). Gói đã cài đặt vẫn được giữ nguyên.','Language pack could not be unpacked.'=>'Gói ngôn ngữ không thể được giải nén.','Language pack is missing a catalog file. The installed pack was left in place.'=>'Gói ngôn ngữ thiếu tệp danh mục. Gói đã cài đặt vẫn được giữ nguyên.','Language pack JSON catalog is invalid. The installed pack was left in place.'=>'Danh mục JSON của gói ngôn ngữ không hợp lệ. Gói đã cài đặt vẫn được giữ nguyên.','Language pack could not be stored. The installed pack was left in place.'=>'Gói ngôn ngữ không thể được lưu trữ. Gói đã cài đặt vẫn được giữ nguyên.','Language pack PHP catalog could not be built. The installed pack was left in place.'=>'Danh mục PHP của gói ngôn ngữ không thể được xây dựng. Gói đã cài đặt vẫn được giữ nguyên.','Warning: The license for %1$s has expired. %2$s'=>'Cảnh báo: Giấy phép cho %1$s đã hết hạn. %2$s','Manage licenses'=>'Quản lý giấy phép','Warning: %1$d plugin(s) have expired licenses: %2$s. %3$s'=>'Cảnh báo: %1$d plugin(s) có giấy phép đã hết hạn: %2$s. %3$s','The license server accepted your key, but this site could not save its active license. Please contact support and mention this message.'=>'Máy chủ giấy phép đã chấp nhận khóa của bạn, nhưng trang này không thể lưu giấy phép hoạt động của nó. Vui lòng liên hệ với bộ phận hỗ trợ và đề cập đến thông điệp này.','PublishPress actions for %s. These tools apply only to this site. If several sites are connected and the requested site is unclear, ask which site to use before calling a tool. Confirm the target site before changing site data.'=>'Các hành động PublishPress cho %s. Những công cụ này chỉ áp dụng cho trang này. Nếu có nhiều trang được kết nối và trang yêu cầu không rõ ràng, hãy hỏi trang nào sẽ sử dụng trước khi gọi một công cụ. Xác nhận trang mục tiêu trước khi thay đổi dữ liệu trang.','WordPress version'=>'Phiên bản WordPress','MCP Adapter version'=>'Phiên bản MCP Adapter','Not active'=>'Không hoạt động','HTTPS'=>'HTTPS','Available'=>'Có sẵn','Required'=>'Bắt buộc','Application passwords'=>'Mật khẩu ứng dụng','Unavailable; check WordPress or security plugin settings'=>'Không có sẵn; kiểm tra cài đặt WordPress hoặc plugin bảo mật','Registered actions'=>'Các hành động đã đăng ký','Selected actions exposed'=>'Các hành động đã chọn được hiển thị','Changes saved.'=>'Thay đổi đã được lưu.','Changes saved. Restart your AI app or refresh its PublishPress connection to update the available actions.'=>'Thay đổi đã được lưu. Khởi động lại ứng dụng AI của bạn hoặc làm mới kết nối PublishPress của nó để cập nhật các hành động khả dụng.','Changes saved. Connect your AI app to continue.'=>'Thay đổi đã được lưu. Kết nối ứng dụng AI của bạn để tiếp tục.','Changes saved. Select at least one available action to continue.'=>'Thay đổi đã được lưu. Chọn ít nhất một hành động khả dụng để tiếp tục.','Update WordPress to continue'=>'Cập nhật WordPress để tiếp tục','WordPress 6.9 or newer is required.'=>'Cần WordPress 6.9 hoặc phiên bản mới hơn.','Open WordPress updates'=>'Mở cập nhật WordPress','Install the MCP Adapter plugin'=>'Cài đặt plugin MCP Adapter','Install the official WordPress MCP Adapter plugin to connect your AI service.'=>'Cài đặt plugin MCP Adapter chính thức của WordPress để kết nối dịch vụ AI của bạn.','Manage plugins'=>'Quản lý các plugin','Set up MCP Adapter'=>'Thiết lập MCP Adapter','Use HTTPS to connect your AI'=>'Sử dụng HTTPS để kết nối AI của bạn','Both WordPress and site addresses must use HTTPS.'=>'Cả địa chỉ WordPress và địa chỉ trang web phải sử dụng HTTPS.','Open site settings'=>'Mở cài đặt trang web','Add a PublishPress plugin with AI actions'=>'Thêm một plugin PublishPress với các hành động AI','You don\'t have any PublishPress plugins installed that support AI actions yet.'=>'Bạn chưa cài đặt bất kỳ plugin PublishPress nào hỗ trợ các hành động AI.','Open PublishPress plugins'=>'Mở các plugin PublishPress','Allow application passwords for your account'=>'Cho phép mật khẩu ứng dụng cho tài khoản của bạn','Create an application password in your WordPress profile for assisted or manual setup.'=>'Tạo một mật khẩu ứng dụng trong hồ sơ WordPress của bạn để thiết lập tự động hoặc thủ công.','Application passwords are unavailable for your account. HTTPS or security plugin settings may need attention.'=>'Mật khẩu ứng dụng không khả dụng cho tài khoản của bạn. Cài đặt HTTPS hoặc plugin bảo mật có thể cần được chú ý.','Open application passwords'=>'Mở mật khẩu ứng dụng','PASTE_YOUR_APPLICATION_PASSWORD_HERE'=>'PASTE_YOUR_APPLICATION_PASSWORD_HERE','Ask my AI to help'=>'Yêu cầu AI của tôi giúp đỡ','Recommended. Ask your AI for a setup script to run on your computer.'=>'Được khuyến nghị. Hãy yêu cầu AI của bạn một script thiết lập để chạy trên máy tính của bạn.','Connect my AI app to PublishPress. Create a setup script and give me the exact terminal command to run it.

1. Ask me to select my AI app and OS (Windows, macOS or Linux). Use interactive choices if available, otherwise numbered options.
2. Create the script using your file tools. Request the specific permission if needed. If you cannot write locally, attach a downloadable script. Only fall back to code with save instructions when neither is possible. Use PowerShell on Windows and an appropriate script on macOS or Linux. Do not stop at explaining access limitations or provide only JSON.
3. Configure this local stdio server:
Name: %3$s
Display name: %4$s
Command: npx
Arguments: -y @automattic/mcp-wordpress-remote@latest
Environment: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Read WP_API_PASSWORD through a hidden terminal prompt.
Hub write access: %5$s. Only individually selected actions are exposed.
4. Check Node.js and npx. If missing, link to the official installer and tell me to reopen the terminal. Back up existing settings. Use a JSON/TOML parser or supported client command to merge only this server, preserving other settings and sites. Stop on invalid configuration or a conflicting endpoint. If replacing an old PublishPress desktop extension for this site, guide me to disable only that extension to avoid duplicate connections. Quote paths and values safely.
5. Give brief run, restart and approval instructions. Verify through the connection or give me a prompt to test in the app: confirm the site URL, list actual tools and perform a read-only lookup. Report whether write tools are available. If expected write tools are missing, ask me to check Allow actions that change site data and the selected actions in Hub, then refresh the connection. Do not claim success from saved configuration alone. Do not test writes during setup. Clarify the target site when ambiguous and ask for review before changing site data.'=>'Kết nối ứng dụng AI của tôi với PublishPress. Tạo một script thiết lập và cho tôi lệnh chính xác trong terminal để chạy nó.

1. Hãy yêu cầu tôi chọn ứng dụng AI và hệ điều hành của tôi (Windows, macOS hoặc Linux). Sử dụng các lựa chọn tương tác nếu có sẵn, nếu không thì sử dụng các tùy chọn được đánh số.
2. Tạo script bằng cách sử dụng các công cụ tệp của bạn. Yêu cầu quyền cụ thể nếu cần thiết. Nếu bạn không thể ghi cục bộ, hãy đính kèm một script có thể tải xuống. Chỉ sử dụng mã với hướng dẫn lưu trữ khi không có tùy chọn nào khả thi. Sử dụng PowerShell trên Windows và một script phù hợp trên macOS hoặc Linux. Đừng dừng lại ở việc giải thích các hạn chế truy cập hoặc chỉ cung cấp JSON.
3. Cấu hình máy chủ stdio cục bộ này:
Tên: %3$s
Tên hiển thị: %4$s
Lệnh: npx
Tham số: -y @automattic/mcp-wordpress-remote@latest
Môi trường: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Đọc WP_API_PASSWORD qua một lời nhắc terminal ẩn.
Quyền truy cập ghi Hub: %5$s. Chỉ các hành động được chọn riêng lẻ mới được hiển thị.
4. Kiểm tra Node.js và npx. Nếu thiếu, liên kết đến trình cài đặt chính thức và yêu cầu tôi mở lại terminal. Sao lưu các cài đặt hiện có. Sử dụng trình phân tích JSON/TOML hoặc lệnh khách hàng được hỗ trợ để chỉ hợp nhất máy chủ này, bảo toàn các cài đặt và trang web khác. Dừng lại khi có cấu hình không hợp lệ hoặc một endpoint xung đột. Nếu thay thế một tiện ích mở rộng PublishPress cũ cho trang web này, hướng dẫn tôi tắt chỉ tiện ích mở rộng đó để tránh các kết nối trùng lặp. Trích dẫn các đường dẫn và giá trị một cách an toàn.
5. Cung cấp hướng dẫn ngắn gọn về việc chạy, khởi động lại và phê duyệt. Xác minh qua kết nối hoặc cho tôi một lời nhắc kiểm tra trong ứng dụng: xác nhận URL trang web, liệt kê các công cụ thực tế và thực hiện một tìm kiếm chỉ đọc. Báo cáo xem các công cụ ghi có khả dụng hay không. Nếu các công cụ ghi dự kiến bị thiếu, yêu cầu tôi kiểm tra Cho phép các hành động thay đổi dữ liệu trang web và các hành động đã chọn trong Hub, sau đó làm mới kết nối. Đừng khẳng định thành công chỉ từ cấu hình đã lưu. Đừng thử ghi trong quá trình thiết lập. Làm rõ trang web mục tiêu khi không rõ ràng và yêu cầu xem xét trước khi thay đổi dữ liệu trang web.</source>
<t i="30">đã bật','disabled'=>'đã tắt','Set up manually'=>'Thiết lập thủ công','Copy the configuration into your MCP client.'=>'Sao chép cấu hình vào khách hàng MCP của bạn.','Actions available through PublishPress Hub.'=>'Các hành động khả dụng thông qua PublishPress Hub.','List WordPress users'=>'Liệt kê người dùng WordPress','Find users by name or role. The optional primitive capability filter checks effective access within each candidate page. Visit all total_pages even when a filtered page is empty. No email addresses or secrets are returned.'=>'Tìm người dùng theo tên hoặc vai trò. Bộ lọc khả năng nguyên thủy tùy chọn kiểm tra quyền truy cập hiệu quả trong từng trang ứng viên. Truy cập tất cả total_pages ngay cả khi một trang đã lọc là trống. Không trả về địa chỉ email hoặc bí mật nào.','Get WordPress user capabilities'=>'Lấy khả năng người dùng WordPress','Resolve exactly one user_id or username and return their identity, roles and effective primitive capabilities. Never guess a user ID. Object-specific permissions require a separate check for that object.'=>'Giải quyết chính xác một user_id hoặc tên người dùng và trả về danh tính, vai trò và khả năng nguyên thủy hiệu quả của họ. Không bao giờ đoán một ID người dùng. Quyền cụ thể cho đối tượng yêu cầu kiểm tra riêng cho đối tượng đó.','Find WordPress content'=>'Tìm nội dung WordPress','Search readable posts, pages or a REST-enabled custom post type. Returns actual IDs, titles and permalinks. Use post_type=page for pages. Resolve ambiguous titles before using a URL. Default status is publish. Private and draft requests enforce WordPress permissions.'=>'Tìm kiếm các bài đăng, trang có thể đọc hoặc một loại bài đăng tùy chỉnh được kích hoạt REST. Trả về các ID, tiêu đề và permalinks thực tế. Sử dụng post_type=page cho các trang. Giải quyết tiêu đề không rõ ràng trước khi sử dụng URL. Trạng thái mặc định là xuất bản. Các yêu cầu riêng tư và bản nháp thực thi quyền WordPress.','List WordPress post types'=>'Liệt kê các loại bài viết WordPress','List readable REST-enabled post types and the capability names used for each type. Use these names for content lookups and permission questions.'=>'Liệt kê các loại bài viết được kích hoạt REST có thể đọc và các tên khả năng được sử dụng cho mỗi loại. Sử dụng những tên này cho các tìm kiếm nội dung và câu hỏi về quyền.','WordPress'=>'WordPress','Create WordPress user'=>'Tạo người dùng WordPress','Create a new user account with a known username, email and one editable role. Ask for missing details. WordPress validates role assignment permissions. MCP rejects administrator and any role granting administrator-level capabilities. A password is generated privately. By default WordPress emails the user a password setup link. Never guess an email or request a password in chat.'=>'Tạo một tài khoản người dùng mới với tên người dùng, email và một vai trò có thể chỉnh sửa đã biết. Yêu cầu thông tin còn thiếu. WordPress xác thực quyền gán vai trò. MCP từ chối vai trò quản trị viên và bất kỳ vai trò nào cấp quyền quản trị viên. Một mật khẩu được tạo ra một cách riêng tư. Theo mặc định, WordPress gửi cho người dùng một liên kết thiết lập mật khẩu qua email. Không bao giờ đoán email hoặc yêu cầu mật khẩu trong chat.','Create WordPress content'=>'Tạo nội dung WordPress','Create a post, page or REST-enabled custom post type. Use post_type=page for pages. Defaults to draft. Publish or schedule only when requested. WordPress checks creation, publishing and author-assignment permissions. Returns the actual ID and permalink.'=>'Tạo một bài viết, trang hoặc loại bài viết tùy chỉnh có hỗ trợ REST. Sử dụng post_type=page cho các trang. Mặc định là nháp. Chỉ xuất bản hoặc lên lịch khi có yêu cầu. WordPress kiểm tra quyền tạo, xuất bản và gán tác giả. Trả về ID thực tế và permalink.','Update WordPress content'=>'Cập nhật nội dung WordPress','Edit an existing post, page or REST-enabled custom post by its verified ID. Find content first if the ID is unknown. Only supplied fields change. WordPress checks object, publishing and author-assignment permissions. No deletion, arbitrary metadata or options are supported.'=>'Chỉnh sửa một bài viết, trang hoặc bài viết tùy chỉnh có hỗ trợ REST đã tồn tại theo ID đã xác minh của nó. Tìm nội dung trước nếu ID không được biết. Chỉ các trường được cung cấp mới thay đổi. WordPress kiểm tra quyền đối tượng, xuất bản và gán tác giả. Không hỗ trợ xóa, metadata tùy ý hoặc tùy chọn.','Use the exact input types shown in discovery.'=>'Sử dụng các loại đầu vào chính xác như được hiển thị trong phát hiện.','You cannot list users.'=>'Bạn không thể liệt kê người dùng.','Provide either a user ID or an exact username.'=>'Cung cấp một ID người dùng hoặc một tên người dùng chính xác.','No matching user belongs to this site.'=>'Không có người dùng nào phù hợp thuộc về trang này.','You cannot inspect this user.'=>'Bạn không thể kiểm tra người dùng này.','Choose a REST-enabled post type.'=>'Chọn một loại bài viết có hỗ trợ REST.','This post type does not support content lookup.'=>'Loại bài viết này không hỗ trợ tìm kiếm nội dung.','MCP tools cannot create users with administrator-level access. Use the WordPress Users screen for this change.'=>'Công cụ MCP không thể tạo người dùng với quyền truy cập cấp quản trị viên. Sử dụng màn hình Người dùng WordPress cho thay đổi này.','Provide at least one content field to update.'=>'Cung cấp ít nhất một trường nội dung để cập nhật.','Choose an existing REST-enabled post type.'=>'Chọn một loại bài viết có hỗ trợ REST đã tồn tại.','This post type does not support content writes.'=>'Loại bài viết này không hỗ trợ ghi nội dung.','You cannot perform this operation.'=>'Bạn không thể thực hiện thao tác này.','Object must be loaded before initializing.'=>'Đối tượng phải được tải trước khi khởi tạo.','This license key is managed in wp-config.php and cannot be edited from the Hub.'=>'Khóa bản quyền này được quản lý trong wp-config.php và không thể chỉnh sửa từ Hub.','No license key found'=>'Không tìm thấy khóa bản quyền','This license key is managed in wp-config.php and cannot be deactivated from the Hub.'=>'Khóa bản quyền này được quản lý trong wp-config.php và không thể bị vô hiệu hóa từ Hub.','Invalid conflict resolution request.'=>'Yêu cầu giải quyết xung đột không hợp lệ.','The selected plugin is not available for activation.'=>'Plugin đã chọn không có sẵn để kích hoạt.','Cleanup was stopped because the selected plugin is not active or the other version is still loaded. Neither copy was deleted.'=>'Quá trình dọn dẹp đã bị dừng lại vì plugin đã chọn không hoạt động hoặc phiên bản khác vẫn đang được tải. Không có bản sao nào bị xóa.','The selected plugin is active, but the other version could not be removed. Please remove it from the Plugins screen.'=>'Plugin đã chọn đang hoạt động, nhưng phiên bản khác không thể bị xóa. Vui lòng xóa nó từ màn hình Plugin.','The selected plugin is no longer active. Please reactivate it from the Plugins screen.'=>'Plugin đã chọn không còn hoạt động. Vui lòng kích hoạt lại từ màn hình Plugin.','No existing license key was found for this plugin.'=>'Không tìm thấy khóa bản quyền nào cho plugin này.','Database Tables'=>'Bảng Cơ sở dữ liệu','PublishPress Plugins'=>'Plugin PublishPress','PublishPress Hub Debug Log'=>'Nhật ký gỡ lỗi Hub PublishPress','Debug Log'=>'Nhật ký gỡ lỗi','The debug log is empty.'=>'Nhật ký gỡ lỗi trống.','Version'=>'Phiên bản','Debug Mode'=>'Chế độ gỡ lỗi','Enabled'=>'Đã bật','Disabled'=>'Đã tắt','Generated At'=>'Được tạo vào','Plugins'=>'Plugin','No PublishPress plugins found.'=>'Không tìm thấy plugin PublishPress nào.','Tables'=>'Bảng','No database table information was available.'=>'Không có thông tin bảng cơ sở dữ liệu nào có sẵn.','Size'=>'Kích thước','Engine'=>'Bộ máy','Rows'=>'Dòng','Collation'=>'Sắp xếp','Charset'=>'Bảng mã','Total Database Size'=>'Tổng kích thước cơ sở dữ liệu','Not installed'=>'Chưa cài đặt','Active'=>'Đang hoạt động','Inactive'=>'Không hoạt động','unknown'=>'không xác định','License'=>'Giấy phép','Free plugin not set for plugin family: %s'=>'Plugin miễn phí chưa được thiết lập cho gia đình plugin: %s','Pro plugin not set for plugin family: %s'=>'Plugin Pro chưa được thiết lập cho gia đình plugin: %s','License activation error. Please try again later or contact support for help.'=>'Lỗi kích hoạt giấy phép. Vui lòng thử lại sau hoặc liên hệ với bộ phận hỗ trợ để được giúp đỡ.','License deactivation error. Please try again later or contact support for help.'=>'Lỗi hủy kích hoạt giấy phép. Vui lòng thử lại sau hoặc liên hệ với bộ phận hỗ trợ để được giúp đỡ.','This license is currently disabled. Please contact support for help.'=>'Giấy phép này hiện đang bị vô hiệu hóa. Vui lòng liên hệ với bộ phận hỗ trợ để được giúp đỡ.','This license has expired. Please contact support to renew it.'=>'Giấy phép này đã hết hạn. Vui lòng liên hệ với bộ phận hỗ trợ để gia hạn.','This license key could not be activated. It may be invalid, blocked, or not authorized for this plugin. Please verify the key and contact PublishPress support if the problem continues.'=>'Khóa giấy phép này không thể được kích hoạt. Nó có thể không hợp lệ, bị chặn hoặc không được ủy quyền cho plugin này. Vui lòng xác minh khóa và liên hệ với bộ phận hỗ trợ PublishPress nếu vấn đề vẫn tiếp diễn.','This license cannot be used for this plugin. Please contact support for help.'=>'Giấy phép này không thể được sử dụng cho plugin này. Vui lòng liên hệ với bộ phận hỗ trợ để được giúp đỡ.','This license does not match the plugin you are trying to activate. Please contact support for assistance.'=>'Giấy phép này không khớp với plugin mà bạn đang cố gắng kích hoạt. Vui lòng liên hệ với bộ phận hỗ trợ để được trợ giúp.','License key does not match our records. Please contact support for assistance.'=>'Khóa giấy phép không khớp với hồ sơ của chúng tôi. Vui lòng liên hệ với bộ phận hỗ trợ để được trợ giúp.','No license key provided. Please enter a valid license key.'=>'Không cung cấp khóa giấy phép. Vui lòng nhập khóa giấy phép hợp lệ.','Your site URL is required to activate the license. Please enter a valid site URL to continue.'=>'URL trang web của bạn là bắt buộc để kích hoạt giấy phép. Vui lòng nhập URL trang web hợp lệ để tiếp tục.','License activation limit reached. Please contact support to upgrade or deactivate on another site.'=>'Giới hạn kích hoạt giấy phép đã đạt. Vui lòng liên hệ với bộ phận hỗ trợ để nâng cấp hoặc hủy kích hoạt trên trang web khác.','This license cannot be activated. Please contact support for help.'=>'Giấy phép này không thể được kích hoạt. Vui lòng liên hệ với bộ phận hỗ trợ để được giúp đỡ.','License server error. Please try again later or contact support for help.'=>'Lỗi máy chủ giấy phép. Vui lòng thử lại sau hoặc liên hệ với bộ phận hỗ trợ để được giúp đỡ.','The license server returned an invalid response. Please try again later or contact support for help.'=>'Máy chủ giấy phép đã trả về phản hồi không hợp lệ. Vui lòng thử lại sau hoặc liên hệ với bộ phận hỗ trợ để được giúp đỡ.','This license is inactive for this site. Please contact support for help.'=>'Giấy phép này không hoạt động cho trang web này. Vui lòng liên hệ với bộ phận hỗ trợ để được giúp đỡ.','Plugin activation failed. Please try again later or contact support for help.'=>'Kích hoạt plugin không thành công. Vui lòng thử lại sau hoặc liên hệ với bộ phận hỗ trợ để được giúp đỡ.','This action is not possible because the plugin is already installed.'=>'Hành động này không thể thực hiện được vì plugin đã được cài đặt.','Plugin deactivation failed. Please try again later or contact support for help.'=>'Hủy kích hoạt plugin không thành công. Vui lòng thử lại sau hoặc liên hệ với bộ phận hỗ trợ để được giúp đỡ.','Plugin family not found. Please contact support for help.'=>'Gia đình plugin không tìm thấy. Vui lòng liên hệ với bộ phận hỗ trợ để được giúp đỡ.','This action is not possible because both free and pro versions are installed. Please uninstall one version to continue.'=>'Hành động này không thể thực hiện được vì cả phiên bản miễn phí và pro đều đã được cài đặt. Vui lòng gỡ cài đặt một phiên bản để tiếp tục.','Plugin installation failed. Please contact support for help.'=>'Cài đặt plugin không thành công. Vui lòng liên hệ với bộ phận hỗ trợ để được giúp đỡ.','This action is not possible because the plugin is not activated. Please activate the plugin and try again.'=>'Hành động này không thể thực hiện được vì plugin chưa được kích hoạt. Vui lòng kích hoạt plugin và thử lại.','Plugin not found in our available plugins list. Please contact support for help.'=>'Plugin không được tìm thấy trong danh sách các plugin có sẵn của chúng tôi. Vui lòng liên hệ với bộ phận hỗ trợ để được giúp đỡ.','This action is not possible because the plugin is not installed. Please install the plugin and try again.'=>'Hành động này không thể thực hiện được vì plugin chưa được cài đặt. Vui lòng cài đặt plugin và thử lại.','Unknown license server error. Please try again later or contact support for help.'=>'Lỗi máy chủ giấy phép không xác định. Vui lòng thử lại sau hoặc liên hệ với bộ phận hỗ trợ để được giúp đỡ.','Sell digital products, programs, and services from your website.'=>'Bán các sản phẩm, chương trình và dịch vụ kỹ thuật số từ trang web của bạn.','Create and manage tags, categories, and taxonomy terms.'=>'Tạo và quản lý thẻ, danh mục và thuật ngữ taxonomy.','Organize taxonomy terms into groups and display them in clouds, tabs, and lists.'=>'Tổ chức các thuật ngữ taxonomy thành nhóm và hiển thị chúng trong đám mây, tab và danh sách.','Define tasks that authors must complete before publishing.'=>'Định nghĩa các nhiệm vụ mà các tác giả phải hoàn thành trước khi xuất bản.','Control who can edit and view your content.'=>'Kiểm soát ai có thể chỉnh sửa và xem nội dung của bạn.','Create, manage and display authors for your content.'=>'Tạo, quản lý và hiển thị các tác giả cho nội dung của bạn.','All the tools you need to improve the block editor.'=>'Tất cả các công cụ bạn cần để cải thiện trình chỉnh sửa khối.','Control your admin area and user roles.'=>'Kiểm soát khu vực quản trị và vai trò người dùng của bạn.','Schedule changes to your posts.'=>'Lên lịch thay đổi cho các bài viết của bạn.','Organize, schedule, and plan your publishing.'=>'Tổ chức, lên lịch và lập kế hoạch cho việc xuất bản của bạn.','Approve and schedule new versions to your published posts.'=>'Phê duyệt và lên lịch phiên bản mới cho các bài viết đã xuất bản của bạn.','Organize your posts into issues or series.'=>'Tổ chức các bài viết của bạn thành các số hoặc loạt bài.','Create custom URLs for your posts and external links.'=>'Tạo các URL tùy chỉnh cho các bài viết và liên kết bên ngoài của bạn.','Create custom statuses and publishing workflows.'=>'Tạo các trạng thái tùy chỉnh và quy trình làm việc xuất bản.','Dependency "%s" not found in container.'=>'Phụ thuộc "%s" không tìm thấy trong container.','Error validating license: %s'=>'Lỗi xác thực giấy phép: %s','Error getting license info: %s'=>'Lỗi lấy thông tin giấy phép: %s','The license server denied this request. This can happen when a license key or site has been blocked. Please contact PublishPress support for help.'=>'Máy chủ giấy phép từ chối yêu cầu này. Điều này có thể xảy ra khi khóa giấy phép hoặc trang web đã bị chặn. Vui lòng liên hệ với hỗ trợ PublishPress để được giúp đỡ.','Too many requests. Please try again later.'=>'Quá nhiều yêu cầu. Vui lòng thử lại sau.','An error occurred while processing your request.'=>'Đã xảy ra lỗi trong quá trình xử lý yêu cầu của bạn.','Template not found: %s'=>'Mẫu không tìm thấy: %s','Path cannot be empty'=>'Đường dẫn không thể để trống','File extension cannot be empty'=>'Đuôi tệp không thể để trống','Invalid file path: null byte detected'=>'Đường dẫn tệp không hợp lệ: byte null được phát hiện','Invalid file path: directory traversal detected'=>'Đường dẫn tệp không hợp lệ: phát hiện truy cập thư mục','Invalid file path: parent directory does not exist: %s'=>'Đường dẫn tệp không hợp lệ: thư mục cha không tồn tại: %s','Invalid file path: unable to resolve path'=>'Đường dẫn tệp không hợp lệ: không thể giải quyết đường dẫn','Invalid file path: operation not allowed outside permitted directories'=>'Đường dẫn tệp không hợp lệ: hoạt động không được phép bên ngoài các thư mục được phép','Download URL failed WordPress validation'=>'URL tải xuống không qua xác thực WordPress','Downloaded plugin file does not exist'=>'Tệp plugin đã tải xuống không tồn tại','Downloaded plugin file is empty'=>'Tệp plugin đã tải xuống là trống','Cannot read downloaded plugin file'=>'Không thể đọc tệp plugin đã tải xuống','Downloaded file is not a valid ZIP archive. The download URL may be returning an error page.'=>'Tệp đã tải xuống không phải là một tập tin ZIP hợp lệ. URL tải xuống có thể đang trả về một trang lỗi.','Failed to unzip plugin file: %s'=>'Không thể giải nén tệp plugin: %s','Failed to unzip plugin file'=>'Không thể giải nén tệp plugin','Failed to activate plugin: %s'=>'Không thể kích hoạt plugin: %s','Resolve conflicts for network-active plugins from Network Admin.'=>'Giải quyết xung đột cho các plugin đang hoạt động trên mạng từ Quản trị Mạng.','Activation recovery failed. Both plugin copies were retained. Please restore the previous version from the Plugins screen.'=>'Khôi phục kích hoạt thất bại. Cả hai bản sao plugin đều được giữ lại. Vui lòng khôi phục phiên bản trước từ màn hình Plugins.','The other plugin could not be deactivated.'=>'Plugin khác không thể bị hủy kích hoạt.','The selected plugin did not remain active.'=>'Plugin đã chọn không còn hoạt động.','The selected plugin could not be activated. Neither copy was deleted and the previous activation settings were restored.'=>'Plugin đã chọn không thể được kích hoạt. Không có bản sao nào bị xóa và các cài đặt kích hoạt trước đó đã được khôi phục.','Failed to delete plugin: %s'=>'Không thể xóa plugin: %s','No update available for this plugin'=>'Không có bản cập nhật nào cho plugin này','Invalid update information for this plugin'=>'Thông tin cập nhật không hợp lệ cho plugin này','Update package not available'=>'Gói cập nhật không có sẵn','Failed to update plugin: %s'=>'Không thể cập nhật plugin: %s','Plugin update failed'=>'Cập nhật plugin thất bại','Invalid download URL provided'=>'URL tải xuống không hợp lệ được cung cấp','Download URL must use HTTP or HTTPS protocol'=>'URL tải xuống phải sử dụng giao thức HTTP hoặc HTTPS','Download URL is not from an allowed domain: %s'=>'URL tải xuống không thuộc miền cho phép: %s','Could not create a temporary package file'=>'Không thể tạo tệp gói tạm thời','Failed to download plugin: %s'=>'Không thể tải xuống plugin: %s','The plugin package download failed'=>'Tải xuống gói plugin thất bại','Failed to get plugin information: %s'=>'Không thể lấy thông tin plugin: %s','MCP Adapter could not be installed or activated. Use the plugin page or contact your host.'=>'MCP Adapter không thể được cài đặt hoặc kích hoạt. Sử dụng trang plugin hoặc liên hệ với nhà cung cấp dịch vụ của bạn.','MCP Adapter activated.'=>'MCP Adapter đã được kích hoạt.','ERR'=>'ERR','.'=>'.']];